import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

public class SettingsReaderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.function.Supplier<Object> call) {
        Object actual;
        try {
            actual = call.get();
        } catch (Throwable t) {
            actual = "threw " + t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    static void done() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static String attempt(Runnable action) {
        try {
            action.run();
            return "no exception";
        } catch (MissingSettingException e) {
            return "MissingSettingException:" + e.key();
        } catch (Throwable t) {
            return "threw " + t.getClass().getSimpleName();
        }
    }

    static SettingsReader reader() {
        Map<String, String> values = new HashMap<>();
        values.put("host", " example.com ");
        values.put("port", " 8080 ");
        values.put("retries", "abc");
        values.put("blank", "   ");
        values.put("nothing", null);
        values.put("offset", "-15");
        return new SettingsReader(values);
    }

    public static void main(String[] args) {
        SettingsReader reader = reader();
        check("find trims the value", Optional.of("example.com"), reader.find("host"));
        check("blank value is empty", Optional.empty(), reader.find("blank"));
        check("null value is empty", Optional.empty(), reader.find("nothing"));
        check("absent key is empty", Optional.empty(), reader.find("missing"));
        check("null key is empty", Optional.empty(), reader.find(null));

        checkCall("require returns the value", "example.com", () -> reader.require("host"));
        check("require throws with the key", "MissingSettingException:missing",
                attempt(() -> reader.require("missing")));
        check("require rejects a blank value", "MissingSettingException:blank",
                attempt(() -> reader.require("blank")));

        check("requireInt parses", 8080, reader.requireInt("port"));
        check("requireInt handles a minus sign", -15, reader.requireInt("offset"));
        check("requireInt rejects non-numbers", "MissingSettingException:retries",
                attempt(() -> reader.requireInt("retries")));
        check("requireInt on a missing key", "MissingSettingException:nope",
                attempt(() -> reader.requireInt("nope")));
        done();
    }
}

