import java.util.Map;
import java.util.Optional;

/**
 * TASK: Complete SettingsReader. The MissingSettingException class above it
 * and the constructor are provided -- do not edit them.
 *
 * - find(key) returns the setting's value, trimmed, as an Optional. A key that
 *   is absent, or whose value is null or blank once trimmed, gives an empty
 *   Optional. A null key also gives an empty Optional.
 *
 * - require(key) returns the value, or throws new MissingSettingException(key)
 *   when it is not there. Use find(key).orElseThrow(() -> ...) -- the supplier
 *   form builds the exception only when it is actually needed.
 *
 * - requireInt(key) returns the value parsed as an int. A value that is not a
 *   whole number (optionally with a leading minus sign) counts as missing and
 *   throws MissingSettingException(key) too -- filter it out of the Optional
 *   rather than catching NumberFormatException.
 *
 * Example: with {"port": " 8080 "}, requireInt("port") -> 8080, while
 * requireInt("host") throws MissingSettingException whose key() is "host".
 */
class MissingSettingException extends RuntimeException {

    private final String key;

    MissingSettingException(String key) {
        super("missing setting: " + key);
        this.key = key;
    }

    public String key() {
        return key;
    }
}

public class SettingsReader {

    private final Map<String, String> values;

    public SettingsReader(Map<String, String> values) {
        this.values = values;
    }

    public Optional<String> find(String key) {
        if (key == null) {
            return Optional.empty();
        }
        return Optional.ofNullable(values.get(key))
                .map(String::trim)
                .filter(value -> !value.isEmpty());
    }

    public String require(String key) {
        return find(key).orElseThrow(() -> new MissingSettingException(key));
    }

    public int requireInt(String key) {
        return find(key)
                .filter(value -> value.matches("-?\\d+"))
                .map(Integer::parseInt)
                .orElseThrow(() -> new MissingSettingException(key));
    }
}
